input.command:
cd /work && ls -la SystemContext.svg && awk '
{
  # count opening and closing tags
  for (i = 1; i <= length($0); i++) {
    c = substr($0, i, 1)
    if (c == "<") {
      # find tag name
      j = i + 1
      name = ""
      while (j <= length($0)) {
        ch = substr($0, j, 1)
        if (ch ~ /[A-Za-z0-9_:-]/) name = name ch
        else break
        j++
      }
      selfclose = 0
      k = j
      while (k <= length($0)) {
        ch = substr($0, k, 1)
        if (ch == "/") { selfclose = 1; break }
        if (ch == ">") break
        k++
      }
      if (name != "" && !selfclose) open[name]++
    }
    if (c == "</") {
      j = i + 2
      name = ""
      while (j <= length($0)) {
        ch = substr($0, j, 1)
        if (ch ~ /[A-Za-z0-9_:-]/) name = name ch
        else break
        j++
      }
      if (name != "") close[name]++
    }
  }
}
END {
  ok = 1
  for (t in open) {
    if (open[t] != close[t]) { print "MISMATCH: " t " open=" open[t] " close=" close[t]; ok = 0 }
  }
  for (t in close) {
    if (!(t in open)) { print "UNEXPECTED CLOSE: " t; ok = 0 }
  }
  if (ok) print "TAG BALANCE OK"
}' SystemContext.svg

